SELECT DATE_TRUNC('month', i.recognized_at) AS month, ROUND(SUM(il.amount),2) AS revenue FROM invoice_lines il JOIN invoices i ON i.invoice_id=il.invoice_id JOIN accounts a ON a.account_id=i.account_id JOIN regions r ON r.region_id=a.billing_region_id WHERE r.name='Europe' AND i.status='posted' AND i.recognized_at BETWEEN DATE '2025-10-01' AND DATE '2025-12-31' GROUP BY month ORDER BY month
